// Simple test script for the POST /check endpoint
const http = require('http');

const testData = {
  rule: 'ctx.amount > 100',
  context: {
    amount: 150,
    user: 'test',
    category: 'electronics'
  }
};

const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/check',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(JSON.stringify(testData))
  }
};

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response Body:', JSON.parse(data));
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

req.write(JSON.stringify(testData));
req.end();

{
  "name": "rules-engine",
  "version": "1.0.0",
  "description": "Dynamic Rule Engine",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test_check.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  }
}

// Test the evalRule function logic from the reference implementation

// Recreate the evalRule function exactly as it should be
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Test cases
const testCases = [
  {
    name: 'Simple amount check',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      }
    },
    expected: true
  },
  {
    name: 'Complex expression with request',
    req: {
      body: {
        rule: 'ctx.amount > 100 && req.headers["x-user-id"] === "123"',
        context: { amount: 150 }
      },
      headers: { 'x-user-id': '123' }
    },
    expected: true
  },
  {
    name: 'String comparison',
    req: {
      body: {
        rule: 'ctx.user === "admin"',
        context: { user: 'admin', role: 'administrator' }
      }
    },
    expected: true
  },
  {
    name: 'False condition',
    req: {
      body: {
        rule: 'ctx.amount < 50',
        context: { amount: 150 }
      }
    },
    expected: false
  }
];

console.log('Testing evalRule function implementation:');
console.log('==========================================\n');

let passed = 0;
let failed = 0;

testCases.forEach((testCase, index) => {
  try {
    const result = evalRule(testCase.req);
    const success = result === testCase.expected;

    console.log(`Test ${index + 1}: ${testCase.name}`);
    console.log(`  Expression: ${testCase.req.body.rule}`);
    console.log(`  Context: ${JSON.stringify(testCase.req.body.context)}`);
    console.log(`  Expected: ${testCase.expected}, Got: ${result}`);

    if (success) {
      console.log(`  ✓ PASS\n`);
      passed++;
    } else {
      console.log(`  ✗ FAIL\n`);
      failed++;
    }
  } catch (error) {
    console.log(`Test ${index + 1}: ${testCase.name}`);
    console.log(`  Expression: ${testCase.req.body.rule}`);
    console.log(`  Error: ${error.message}`);
    console.log(`  ✗ FAIL (Exception)\n`);
    failed++;
  }
});

console.log(`\nSummary: ${passed} passed, ${failed} failed`);

// Also test the Function constructor behavior directly
console.log('\n\nDirect Function constructor test:');
console.log('=================================\n');

// This is the core logic from evalRule
const expr = 'ctx.amount > 100';
const context = { amount: 150 };
const req = { headers: { 'x-user-id': '123' } };

try {
  // This is what evalRule does internally
  const result = Function('ctx', 'req', `return (${expr});`)(context, req);
  console.log(`Expression: ${expr}`);
  console.log(`Context: ${JSON.stringify(context)}`);
  console.log(`Result: ${result}`);
  console.log('✓ Function constructor works correctly');
} catch (error) {
  console.log(`Error with Function constructor: ${error.message}`);
}

