const request = require('supertest');
const app = require('./app');

// Test the POST /check endpoint
async function testCheckEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Basic rule evaluation with context
  console.log('Test 1: Basic rule evaluation with context');
  const test1 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    });

  console.log('Response:', JSON.stringify(test1.body, null, 2));
  console.log('Status:', test1.status);
  console.log('Expected result: true\n');

  // Test 2: Rule evaluation with direct request access
  console.log('Test 2: Rule evaluation with direct request access');
  const test2 = await request(app)
    .post('/check')
    .set('X-User-Id', '123')
    .send({
      rule: 'req.get("X-User-Id") === "123"',
      context: {}
    });

  console.log('Response:', JSON.stringify(test2.body, null, 2));
  console.log('Status:', test2.status);
  console.log('Expected result: true\n');

  // Test 3: Missing rule field
  console.log('Test 3: Missing rule field');
  const test3 = await request(app)
    .post('/check')
    .send({
      context: { amount: 50 }
    });

  console.log('Response:', JSON.stringify(test3.body, null, 2));
  console.log('Status:', test3.status);
  console.log('Expected: 400 Bad Request\n');

  // Test 4: Rule with syntax error
  console.log('Test 4: Rule with syntax error');
  const test4 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount >',
      context: { amount: 50 }
    });

  console.log('Response:', JSON.stringify(test4.body, null, 2));
  console.log('Status:', test4.status);
  console.log('Expected: 500 Internal Server Error\n');

  // Test 5: Complex rule with multiple conditions
  console.log('Test 5: Complex rule with multiple conditions');
  const test5 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100 && ctx.currency === "USD"',
      context: { amount: 150, currency: 'USD' }
    });

  console.log('Response:', JSON.stringify(test5.body, null, 2));
  console.log('Status:', test5.status);
  console.log('Expected result: true\n');

  // Test 6: Rule without context (should use empty object)
  console.log('Test 6: Rule without context');
  const test6 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.foo === undefined'
    });

  console.log('Response:', JSON.stringify(test6.body, null, 2));
  console.log('Status:', test6.status);
  console.log('Expected result: true\n');
}

// Run the tests
testCheckEndpoint().catch(console.error);

