const mockRequests = [
  {
    name: 'Test 1: ctx.amount > 100 with amount 150',
    body: {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    expected: true
  },
  {
    name: 'Test 2: ctx.amount < 50 with amount 150',
    body: {
      rule: 'ctx.amount < 50',
      context: { amount: 150 }
    },
    expected: false
  },
  {
    name: 'Test 3: Complex expression with multiple conditions',
    body: {
      rule: 'ctx.amount > 100 && ctx.user.role === "admin"',
      context: { 
        amount: 150,
        user: { role: 'admin' }
      }
    },
    expected: true
  },
  {
    name: 'Test 4: Access to req object',
    body: {
      rule: 'req.body.context.amount > 100',
      context: { amount: 150 }
    },
    expected: true
  }
];

// Direct implementation of evalRule from app.js
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Run tests
console.log('Running tests against evalRule function:');
console.log('=========================================\n');

let passed = 0;
let failed = 0;

mockRequests.forEach((testCase, index) => {
  console.log(`${index + 1}. ${testCase.name}`);
  console.log(`   Rule: "${testCase.body.rule}"`);
  console.log(`   Context: ${JSON.stringify(testCase.body.context)}`);

  try {
    const result = evalRule({ body: testCase.body });
    const boolResult = Boolean(result);
    const success = boolResult === testCase.expected;

    console.log(`   Result: ${result} (boolean: ${boolResult})`);
    console.log(`   Expected: ${testCase.expected}`);
    console.log(`   Status: ${success ? '✓ PASSED' : '✗ FAILED'}`);

    if (success) {
      passed++;
    } else {
      failed++;
    }
  } catch (error) {
    console.log(`   Error: ${error.message}`);
    console.log(`   Status: ✗ FAILED`);
    failed++;
  }

  console.log('');
});

console.log('=========================================');
console.log(`Summary: ${passed} passed, ${failed} failed`);

if (failed === 0) {
  console.log('All tests passed! The evalRule function works correctly.');
} else {
  console.log('Some tests failed. Please check the implementation.');
}

