// Test script for the POST /check endpoint
const app = require('./app.js');
const request = require('supertest');

// Test cases following the reference implementation
async function runTests() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Basic rule evaluation
  console.log('Test 1: Basic rule evaluation');
  const test1 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    });
  console.log('Response:', JSON.stringify(test1.body, null, 2));
  console.log('Expected: result should be true\n');

  // Test 2: Rule evaluation with false result
  console.log('Test 2: Rule evaluation with false result');
  const test2 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    });
  console.log('Response:', JSON.stringify(test2.body, null, 2));
  console.log('Expected: result should be false\n');

  // Test 3: Accessing request properties
  console.log('Test 3: Accessing request properties');
  const test3 = await request(app)
    .post('/check')
    .set('X-User-Id', '123')
    .send({
      rule: 'req.get("X-User-Id") === "123" && ctx.user === "admin"',
      context: { user: 'admin' }
    });
  console.log('Response:', JSON.stringify(test3.body, null, 2));
  console.log('Expected: result should be true\n');

  // Test 4: Missing rule field
  console.log('Test 4: Missing rule field');
  const test4 = await request(app)
    .post('/check')
    .send({
      context: { amount: 150 }
    });
  console.log('Response:', JSON.stringify(test4.body, null, 2));
  console.log('Expected: error about missing rule field\n');

  // Test 5: Invalid rule expression
  console.log('Test 5: Invalid rule expression');
  const test5 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount >',
