// Test the endpoint with various rule expressions
async function testCheckEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Simple rule evaluation
  console.log('Test 1: Simple comparison rule');
  const test1 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    });
  console.log(`Response: ${JSON.stringify(test1.body)}`);
  console.log(`Expected: result should be true (150 > 100)`);
  console.log(`Status: ${test1.statusCode === 200 ? 'PASS' : 'FAIL'}\n`);

  // Test 2: Rule using request properties
  console.log('Test 2: Rule using request properties');
  const test2 = await request(app)
    .post('/check')
    .send({
      rule: 'req.method === "POST"',
      context: { data: 'test' }
    });
  console.log(`Response: ${JSON.stringify(test2.body)}`);
  console.log(`Expected: result should be true (method is POST)`);
  console.log(`Status: ${test2.statusCode === 200 ? 'PASS' : 'FAIL'}\n`);

  // Test 3: Complex rule with logical operators
  console.log('Test 3: Complex rule with logical operators');
  const test3 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.age >= 18 && ctx.country === "US"',
      context: { age: 21, country: 'US' }
    });
  console.log(`Response: ${JSON.stringify(test3.body)}`);
  console.log(`Expected: result should be true (21 >= 18 and country is US)`);
  console.log(`Status: ${test3.statusCode === 200 ? 'PASS' : 'FAIL'}\n`);

  // Test 4: Missing rule parameter
  console.log('Test 4: Missing rule parameter');
  const test4 = await request(app)
    .post('/check')
    .send({
      context: { amount: 50 }
    });
  console.log(`Response: ${JSON.stringify(test4.body)}`);
  console.log(`Expected: 400 Bad Request with error message`);
  console.log(`Status: ${test4.statusCode === 400 ? 'PASS' : 'FAIL'}\n`);

  // Test 5: Invalid JavaScript expression
  console.log('Test 5: Invalid JavaScript expression');
  const test5 = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > ',
      context: { amount: 50 }
    });
  console.log(`Response: ${JSON.stringify(test5.body)}`);
  console.log(`Expected: 400 Bad Request with syntax error`);
  console.log(`Status: ${test5.statusCode === 400 ? 'PASS' : 'FAIL'}\n`);

